#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
int lastValue = -1;

void setup() {
  pinMode(A0, INPUT);
  display.setBrightness(7, true);
}

void loop() {
  const int raw = analogRead(A0);
  const int value = (long)raw * 9999L / 1023L;
  if (value != lastValue) {
    display.showNumberDec(value, false, 4, 0);
    lastValue = value;
  }
}
